import secrets

major = [("愚人","0"),("魔术师","1"),("女祭司","2"),("皇后","3"),("皇帝","4"),("教皇","5"),("恋人","6"),("战车","7"),("力量","8"),("隐士","9"),("命运之轮","10"),("正义","11"),("吊人","12"),("死神","13"),("节制","14"),("恶魔","15"),("塔","16"),("星星","17"),("月亮","18"),("太阳","19"),("审判","20"),("世界","21")]

suits = {
 "权杖":["权杖王牌","权杖二","权杖三","权杖四","权杖五","权杖六","权杖七","权杖八","权杖九","权杖十","权杖侍从","权杖骑士","权杖王后","权杖国王"],
 "圣杯":["圣杯王牌","圣杯二","圣杯三","圣杯四","圣杯五","圣杯六","圣杯七","圣杯八","圣杯九","圣杯十","圣杯侍从","圣杯骑士","圣杯王后","圣杯国王"],
 "宝剑":["宝剑王牌","宝剑二","宝剑三","宝剑四","宝剑五","宝剑六","宝剑七","宝剑八","宝剑九","宝剑十","宝剑侍从","宝剑骑士","宝剑王后","宝剑国王"],
 "星币":["星币王牌","星币二","星币三","星币四","星币五","星币六","星币七","星币八","星币九","星币十","星币侍从","星币骑士","星币王后","星币国王"],
}

deck = []
for n, num in major:
    deck.append((n, "大阿卡纳", num))
for suit, cards in suits.items():
    for c in cards:
        deck.append((c, suit, None))

assert len(deck) == 78, len(deck)

positions = ["状况", "建议", "结果"]
drawn = []
pool = list(deck)
for _ in range(3):
    idx = secrets.randbelow(len(pool))
    drawn.append(pool.pop(idx))

for pos, (name, cat, meta) in zip(positions, drawn):
    orient = secrets.choice(["正位", "逆位"])
    if cat == "大阿卡纳":
        print("%s: %s | 大阿卡纳(序号%s) | %s" % (pos, name, meta, orient))
    else:
        print("%s: %s | 小阿卡纳(%s) | %s" % (pos, name, cat, orient))

print("随机源: secrets | 牌库: 韦特78张 | 无重复")", "path": "draw_three.py"}

